// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.screenimport timber.log.Timberimport android.accessibilityservice.AccessibilityServiceimport android.graphics.Rectimport android.os.Buildimport android.view.accessibility.AccessibilityNodeInfoimport com.roshan.persona.vision.ocr.BoundingBoximport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Accessibility UI Element Detector (Module 6 v4 — Step 6.6, REAL implementation). * * Detects UI elements (buttons, icons, input fields, links) by walking the * [AccessibilityNodeInfo] tree exposed by the active [AccessibilityService]. * Replaces [FakeUiElementDetector] in the Hilt graph. * * ## How it works * * ``` * AccessibilityService.getRootInActiveWindow() → AccessibilityNodeInfo (root) *   ↓ * DFS traversal of node tree: *   - For each node with text/contentDescription → emit UiElement *   - Bounding box (pixel coords in Rect) → normalized (0..1) *   - Class name maps to label: *       android.widget.Button        → "button" *       android.widget.EditText      → "input" *       android.widget.ImageView     → "icon" *       android.widget.TextView      → "text" *       android.widget.ImageButton   → "icon button" *       android.widget.CheckBox      → "checkbox" *       android.widget.RadioButton   → "radio button" *       android.widget.Switch        → "switch" *       android.view.View            → "view" *       default                      → "element" *   ↓ * Return List<UiElement> * ``` * * ## Why this beats ML Kit object detection for UI * *  - ML Kit object detection sees pixels only — it can find a "rectangle" *    but can't read the "Send" text on it. *  - Accessibility nodes have semantic labels (button, input, etc.) + text *    content + clickable state. This is what TalkBack uses. *  - 100% accurate for native Android UI; works on any app that exposes *    an accessibility tree (most do). * * ## Privacy (per strategy v4) * *  - UI element tree is processed in RAM — never persisted. *  - Only element label + text + bounding box are extracted; no node *    internals (event handlers, etc.) are inspected. *  - Requires the user's BIND_ACCESSIBILITY_SERVICE permission. * * @see <a href="https://developer.android.com/reference/android/view/accessibility/AccessibilityNodeInfo">AccessibilityNodeInfo</a> */@Singletonclass AccessibilityUiElementDetector @Inject constructor() : UiElementDetector {    @Volatile    private var serviceRef: AccessibilityService? = null    override suspend fun detect(imageBytes: ByteArray): List<UiElement> {        val service = serviceRef ?: run {            Timber.tag(TAG).w("No AccessibilityService registered — returning empty UI element list.")            return emptyList()        }        return try {            val root = service.rootInActiveWindow ?: run {                Timber.tag(TAG).d("getRootInActiveWindow() returned null.")                return emptyList()            }            // Resolve screen dimensions from the service's display metrics.            // AccessibilityService extends Service, so getResources() is available.            val metrics = service.resources.displayMetrics            val screenWidth = metrics.widthPixels.coerceAtLeast(1)            val screenHeight = metrics.heightPixels.coerceAtLeast(1)            try {                val elements = mutableListOf<UiElement>()                val bounds = Rect()                traverseNode(root, elements, bounds, screenWidth, screenHeight)                Timber.tag(TAG).d("Detected ${elements.size} UI elements.")                elements            } finally {                root.recycle()            }        } catch (t: Throwable) {            Timber.tag(TAG).e("UI element detection failed.", t)            emptyList()        }    }    /**     * Register the active [AccessibilityService] instance. Called by     * `NousAccessibilityService.onServiceConnected()` (Module 10).     */    fun registerService(service: AccessibilityService) {        serviceRef = service        Timber.tag(TAG).i("AccessibilityService registered — UI element detection available.")    }    /** Unregister the service. */    fun unregisterService() {        serviceRef = null    }    // ─── Internal ──────────────────────────────────────────────────────────    /** DFS traversal of the accessibility node tree. */    private fun traverseNode(        node: AccessibilityNodeInfo,        out: MutableList<UiElement>,        reuseBounds: Rect,        screenWidth: Int,        screenHeight: Int,    ) {        // Visit current node.        val text = node.text?.toString()?.takeIf { it.isNotBlank() }        val contentDesc = node.contentDescription?.toString()?.takeIf { it.isNotBlank() }        val label = labelFor(node)        // Emit a UiElement if the node has text OR contentDescription OR is        // clickable AND has a non-empty bounding box.        if ((text != null || contentDesc != null || node.isClickable) && label != null) {            node.getBoundsInScreen(reuseBounds)            if (reuseBounds.width() > 0 && reuseBounds.height() > 0) {                val element = buildUiElement(label, text ?: contentDesc, reuseBounds, screenWidth, screenHeight, node)                if (element != null) out.add(element)            }        }        // Recurse into children.        for (i in 0 until node.childCount) {            val child = node.getChild(i) ?: continue            try {                traverseNode(child, out, reuseBounds, screenWidth, screenHeight)            } finally {                child.recycle()            }        }    }    private fun buildUiElement(        label: String,        text: String?,        bounds: Rect,        screenWidth: Int,        screenHeight: Int,        node: AccessibilityNodeInfo,    ): UiElement? {        val normW = screenWidth.toFloat().coerceAtLeast(1f)        val normH = screenHeight.toFloat().coerceAtLeast(1f)        val left = (bounds.left.toFloat() / normW).coerceIn(0f, 0.999f)        val top = (bounds.top.toFloat() / normH).coerceIn(0f, 0.999f)        val right = (bounds.right.toFloat() / normW).coerceIn(left + 0.001f, 1f)        val bottom = (bounds.bottom.toFloat() / normH).coerceIn(top + 0.001f, 1f)        val bbox = try {            BoundingBox(left = left, top = top, right = right, bottom = bottom)        } catch (iae: IllegalArgumentException) {            Timber.tag(TAG).w("Skipping element with invalid bbox: $bounds", iae)            return null        }        return UiElement(            label = label,            text = text,            boundingBox = bbox,            confidence = 0.99f,  // Accessibility nodes are authoritative.            isInteractive = node.isClickable || node.isFocusable,        )    }    /** Map an Android View class name to a NOUS UI element label. */    private fun labelFor(node: AccessibilityNodeInfo): String? {        val className = node.className?.toString() ?: return null        return when {            className.contains("Button", ignoreCase = true) -> "button"            className.contains("ImageButton", ignoreCase = true) -> "icon button"            className.contains("EditText", ignoreCase = true) -> "input"            className.contains("TextView", ignoreCase = true) -> "text"            className.contains("ImageView", ignoreCase = true) -> "icon"            className.contains("CheckBox", ignoreCase = true) -> "checkbox"            className.contains("RadioButton", ignoreCase = true) -> "radio button"            className.contains("Switch", ignoreCase = true) -> "switch"            className.contains("WebView", ignoreCase = true) -> "web view"            className.contains("RecyclerView", ignoreCase = true) -> "list"            className.contains("ScrollView", ignoreCase = true) -> "scroll view"            else -> "element"        }    }    private companion object {        private const val TAG = "AccessibilityUiDetector"    }}